{
  "conversations": [
    {
      "title": "State my dietary restrictions",
      "lines": [
        {
          "speaker": "you",
          "text": "I'm vegan."
        },
        {
          "speaker": "partner",
          "text": "Does that mean no meat, fish, eggs, or dairy?"
        },
        {
          "speaker": "you",
          "text": "That's right."
        },
        {
          "speaker": "partner",
          "text": "No dashi or honey either?"
        },
        {
          "speaker": "you",
          "text": "That's right."
        },
        {
          "speaker": "partner",
          "text": "We can help with that."
        }
      ],
      "vocab": [
        "vegan",
        "meat",
        "fish",
        "dairy",
        "dashi",
        "honey"
      ]
    },
    {
      "title": "Ask about hidden ingredients",
      "lines": [
        {
          "speaker": "you",
          "text": "Does this contain dashi?"
        },
        {
          "speaker": "partner",
          "text": "Yes, it does."
        },
        {
          "speaker": "partner",
          "text": "No, it doesn't.",
          "or": true
        },
        {
          "speaker": "you",
          "text": "Does it contain fish sauce?"
        },
        {
          "speaker": "partner",
          "text": "Yes, it does."
        },
        {
          "speaker": "partner",
          "text": "No, it doesn't.",
          "or": true
        },
        {
          "speaker": "you",
          "text": "Could you make it without dashi?"
        },
        {
          "speaker": "partner",
          "text": "Yes, we can."
        },
        {
          "speaker": "partner",
          "text": "No, we can't.",
          "or": true
        },
        {
          "speaker": "you",
          "text": "Thank you."
        }
      ],
      "vocab": [
        "contain",
        "dashi",
        "fish",
        "sauce",
        "without",
        "check"
      ]
    },
    {
      "title": "Order vegan dishes",
      "lines": [
        {
          "speaker": "you",
          "text": "What vegan dishes do you have?"
        },
        {
          "speaker": "partner",
          "text": "We have tofu salad and vegetable sushi."
        },
        {
          "speaker": "you",
          "text": "I'll have both, please."
        },
        {
          "speaker": "partner",
          "text": "Anything else?"
        },
        {
          "speaker": "you",
          "text": "Yes, miso soup, please."
        },
        {
          "speaker": "you",
          "text": "No, that's everything.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "Okay."
        }
      ],
      "vocab": [
        "dish",
        "tofu",
        "salad",
        "vegetable",
        "sushi",
        "both"
      ]
    }
  ]
}
